<?php
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
$s=db()->prepare("SELECT COUNT(*) cnt,COALESCE(SUM(amount),0) total FROM payments WHERE status='completed' AND DATE(payment_date) BETWEEN ? AND ?");$s->execute([$from,$to]);$summary=$s->fetch();
$cs=db()->prepare('SELECT COUNT(*) FROM clients WHERE DATE(created_at) BETWEEN ? AND ?');$cs->execute([$from,$to]);$newClients=(int)$cs->fetchColumn();
$m=db()->query("SELECT COUNT(*) total,SUM(status='active' AND end_date>=CURDATE()) active,SUM(status='expired' OR end_date<CURDATE()) expired FROM memberships")->fetch();
$byPlan=db()->query("SELECT p.name,COUNT(m.id) total,SUM(m.status='active' AND m.end_date>=CURDATE()) active FROM plans p LEFT JOIN memberships m ON m.plan_id=p.id GROUP BY p.id ORDER BY total DESC")->fetchAll();
$daily=db()->prepare("SELECT DATE(payment_date) day,SUM(amount) total,COUNT(*) operations FROM payments WHERE status='completed' AND DATE(payment_date) BETWEEN ? AND ? GROUP BY DATE(payment_date) ORDER BY day DESC");$daily->execute([$from,$to]);$rows=$daily->fetchAll();
?>
<section class="card panel"><div class="panel-head"><h2>Rango del reporte</h2><div class="report-tools"><a class="btn" href="index.php?view=reports&from=<?=h($from)?>&to=<?=h($to)?>&export=csv">Descargar CSV ↓</a><button class="btn" onclick="window.print()">Imprimir</button></div></div><form method="get" class="form-grid"><input type="hidden" name="view" value="reports"><label>Desde<input type="date" name="from" value="<?=h($from)?>"></label><label>Hasta<input type="date" name="to" value="<?=h($to)?>"></label><div class="form-actions"><button class="btn primary">Actualizar reporte</button></div></form></section>
<div class="grid stats"><article class="card stat"><div class="stat-top">Ingresos en el período</div><div class="stat-value" style="font-size:22px"><?=money($summary['total'])?></div><div class="stat-foot"><?=h($from)?> — <?=h($to)?></div></article><article class="card stat"><div class="stat-top">Operaciones registradas</div><div class="stat-value"><?=$summary['cnt']?></div><div class="stat-foot">Pagos completados</div></article><article class="card stat"><div class="stat-top">Clientes nuevos</div><div class="stat-value"><?=$newClients?></div><div class="stat-foot">Altas en el período</div></article><article class="card stat"><div class="stat-top">Membresías activas</div><div class="stat-value"><?=$m['active']??0?></div><div class="stat-foot">Vencidas: <?=$m['expired']??0?></div></article></div>
<section class="card panel"><div class="panel-head"><h2>Resumen de membresías por plan</h2><small>Total de membresías históricas y vigentes</small></div><table><thead><tr><th>PLAN</th><th>VIGENTES</th><th>TOTAL HISTÓRICO</th></tr></thead><tbody><?php foreach($byPlan as $p): ?><tr><td><?=h($p['name'])?></td><td><?=$p['active']??0?></td><td><?=$p['total']?></td></tr><?php endforeach; ?><?php if(!$byPlan): ?><tr><td colspan="3" class="empty">No hay planes configurados.</td></tr><?php endif; ?></tbody></table></section>
<section class="card panel"><div class="panel-head"><h2>Detalle financiero por día</h2><small>Moneda: bolivianos (Bs)</small></div><div class="table-wrap"><table><thead><tr><th>FECHA</th><th>OPERACIONES</th><th>INGRESOS</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=date('d/m/Y',strtotime($r['day']))?></td><td><?=$r['operations']?></td><td><b><?=money($r['total'])?></b></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="3" class="empty">No existen pagos completados en ese período.</td></tr><?php endif; ?></tbody></table></div></section>
